function label3(zh,en,ko){return state.lang==='zht'?toTraditional(zh):state.lang==='zh'?toSimplified(zh):state.lang==='ko'?ko:state.lang==='ja'?(JA_PHRASES[zh]||en):en}
/* V10.106: one authoritative, five-language, reader-first HRV glossary.
   Scores and clinical thresholds are unchanged. Neither indicator identifies mood. */
function dpHrvPlain(key){
 const phrases={
  rmssd:{
   zht:'了解安靜休息時，身體是否能像平常一樣放鬆與恢復。偏低可能是剛活動、緊張或休息不足；偏高也可能受當時活動或量測條件影響。',
   zh:'了解安静休息时，身体能否像平常一样放松与恢复。偏低可能是刚运动、紧张或休息不足；偏高也可能受当时活动或测量条件影响。',
   en:'Shows whether your pet can relax and recover as usual at rest. Low readings may follow activity, stress or poor rest; highs can also reflect different activity or recording conditions.',
   ko:'조용히 쉴 때 평소처럼 몸을 이완하고 회복하는지 봅니다. 낮으면 최근 활동·긴장·휴식 부족 때문일 수 있고, 높으면 활동이나 측정 조건이 달랐을 수 있습니다.',
   ja:'安静時に普段どおりリラックスして回復できるかを見る指標です。低い場合は直前の運動・緊張・休息不足、高い場合も活動や計測条件の違いが考えられます。'
  },
  sdnn:{
   zht:'了解安靜時心跳是否維持平常的自然變化。偏低可能與疲累、休息不足有關；偏高可能與剛活動或訊號干擾有關。',
   zh:'了解安静时心跳是否保持平常的自然变化。偏低可能与疲劳、休息不足有关；偏高可能与刚运动或信号干扰有关。',
   en:'Shows whether quiet-time heartbeats keep their usual natural variation. Lows may relate to fatigue or poor rest; highs may reflect recent movement or signal interference.',
   ko:'조용히 쉴 때 심박이 평소처럼 자연스럽게 변하는지 봅니다. 낮으면 피로나 휴식 부족, 높으면 최근 활동이나 신호 간섭 때문일 수 있습니다.',
   ja:'安静時の心拍に普段どおりの自然な変化があるかを見る指標です。低い場合は疲れや休息不足、高い場合は直前の運動や信号の乱れが考えられます。'
  },
  rmssdShort:{zht:'休息時能否像平常一樣放鬆、恢復；連續明顯偏低要留意。',zh:'休息时能否像平常一样放松、恢复；连续明显偏低要留意。',en:'Whether resting and recovery look usual; repeated lows merit attention.',ko:'쉬고 회복하는 상태가 평소와 비슷한지 봅니다. 계속 낮다면 확인이 필요합니다.',ja:'休息と回復が普段に近いか。低い状態が続くときは確認を。'},
  sdnnShort:{zht:'心跳是否保有平常的自然變化；連續明顯偏低要留意。',zh:'心跳是否保持平常的自然变化；连续明显偏低要留意。',en:'Whether natural heartbeat variation looks usual; repeated lows merit attention.',ko:'심박의 자연스러운 변화가 평소와 비슷한지 봅니다. 계속 낮다면 확인이 필요합니다.',ja:'心拍の自然な変化が普段に近いか。低い状態が続くときは確認を。'},
  calm:{
   zht:'看看牠安靜休息時，心跳、呼吸與恢復狀態是否和平常差不多。明顯偏離時，先確認近期活動、休息與佩戴情況。',
   zh:'看看它安静休息时，心跳、呼吸与恢复状态是否和平常差不多。明显偏离时，先确认近期活动、休息与佩戴情况。',
   en:'Shows whether heart rate, breathing and recovery look usual during quiet rest. If they differ, check recent activity, rest and collar fit.',
   ko:'편히 쉴 때 심박·호흡·회복 상태가 평소와 비슷한지 봅니다. 차이가 크면 최근 활동·휴식·목줄 착용을 확인하세요.',
   ja:'安静時の心拍・呼吸・回復が普段に近いかを見ます。差が大きい場合は最近の活動・休息・装着状態を確認してください。'
  },
  difference:{zht:'簡單說：RMSSD 幫助看休息與恢復是否如常；SDNN 幫助看心跳的自然變化是否如常。兩項都只跟牠自己的相似量測比較。',zh:'简单说：RMSSD 帮助看休息与恢复是否如常；SDNN 帮助看心跳的自然变化是否如常。两项都只与它自己类似条件下的测量比较。',en:'In short: RMSSD informs rest and recovery; SDNN informs usual natural heartbeat variation. Compare both with this pet’s own readings taken under similar conditions.',ko:'간단히 RMSSD는 휴식·회복이 평소와 비슷한지, SDNN은 심박의 자연스러운 변화가 평소와 비슷한지 살핍니다. 둘 다 비슷한 조건에서 측정한 자신의 수치와 비교하세요.',ja:'RMSSDは休息と回復、SDNNは心拍の自然な変化が普段に近いかを見る指標です。どちらも似た条件で測定したこの子自身の記録と比べてください。'},
  mood:{zht:'不能單靠心跳、RMSSD 或 SDNN 判斷牠「開心」還是「不開心」。興奮、緊張、活動和身體不舒服，都可能出現相似變化；請搭配食慾、活動、姿勢及日常行為觀察。',zh:'不能只靠心跳、RMSSD 或 SDNN 判断它“开心”还是“不开心”。兴奋、紧张、运动和身体不舒服，都可能出现类似变化；请结合食欲、活动、姿势和日常行为观察。',en:'Heart rate, RMSSD and SDNN alone cannot reliably label a pet as happy or unhappy. Excitement, stress, activity and discomfort can produce similar changes. Also watch appetite, movement, posture and usual behavior.',ko:'심박수·RMSSD·SDNN만으로 행복한지 불행한지 판단할 수 없습니다. 흥분·긴장·활동·불편함이 비슷한 변화를 일으킬 수 있습니다. 식욕·활동·자세·평소 행동도 함께 살펴보세요.',ja:'心拍数・RMSSD・SDNNだけでは「うれしい／うれしくない」を正確に判定できません。興奮・緊張・運動・不調でも似た変化が出ます。食欲・活動・姿勢・いつもの行動も確認してください。'}
 };
 return (phrases[key]||phrases.mood)[state.lang]||phrases[key]?.zht||'';
}
function dpHrvLocale(zht,zh,en,ko,ja){return ({zht,zh,en,ko,ja})[state.lang]||en;}
function niceDogText(){const d=currentDog();return (state.lang==='zh'||state.lang==='zht')?`${d.name} · ${breedText(d)} · ${d.age} ${state.lang==='zht'?'歲':'岁'} · ${d.weight} kg`:state.lang==='ko'?`${d.name} · ${d.breed.ko} · ${d.age}세 · ${d.weight}kg`:state.lang==='ja'?`${d.name} · ${breedText(d)} · ${d.age}歳 · ${d.weight} kg`:`${d.name} · ${d.breed.en} · ${d.age} yrs · ${d.weight} kg`}
function nightArt(){return `<svg viewBox="0 0 96 90" class="night-art" aria-hidden="true"><defs><linearGradient id="ng" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#626bbd"/><stop offset="1" stop-color="#b5bbf5"/></linearGradient></defs><rect width="96" height="90" rx="16" fill="url(#ng)"/><circle cx="65" cy="27" r="14" fill="#fff6cf"/><circle cx="73" cy="22" r="13" fill="#8c98e1"/><g fill="white"><circle cx="19" cy="20" r="1.5"/><circle cx="39" cy="14" r="1.7"/><circle cx="78" cy="53" r="1.2"/></g><path fill="#383d80" d="M0 76Q30 64 49 73Q69 58 96 70V90H0Z"/><path d="M18 70c8-17 20-19 26-9 4-6 11-8 15-2 9 5 8 16-8 17H20Z" fill="#4e548e"/><circle cx="32" cy="61" r="3" fill="#4e548e"/></svg>`}

function kv(k,v){return `<div class="row spread"><span class="sm muted">${t(k)}</span><span class="sm strong">${v}</span></div>`}
function bigHeader(title,sub=''){return `<div class="view-header"><h1 class="app-title">${title}</h1>${sub?`<div class="subtitle mt8">${sub}</div>`:''}</div>`}
function card(title,content,extra=''){return `<section class="card ${extra}">${title?`<div class="row spread mb8"><h2 class="section-title">${title}</h2></div>`:''}${content}</section>`}
function button(label,action,klass='cta secondary',attrs=''){return `<button class="${klass}" data-action="${action}" ${attrs}>${label}</button>`}
function toast(msg){const x=$('.toast');if(x)x.remove();const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.setAttribute('aria-live','polite');n.setAttribute('aria-atomic','true');n.textContent=msg;$('.app-shell').appendChild(n);setTimeout(()=>n.remove(),2300)}
function panel(iconTxt,label,description,action){return `<button class="menu-item" data-action="${action}"><span class="menu-ic">${iconTxt}</span><span class="grow"><div class="menu-name">${label}</div><div class="menu-desc">${description}</div></span><span class="menu-chevron">›</span></button>`}
