  const src=k<6?prior:today,m=k<6?1260+k*30:(k-6)*30;
  const quiet=[];
  for(let i=m;i<m+30;i++)if(Number.isFinite(src.rest[i])&&src.rest[i]>=50&&Number.isFinite(src.breath[i])&&src.breath[i]>0)quiet.push(src.breath[i]);
