function dpMinutesText(min){const h=Math.floor(Math.abs(min)/60),m=Math.round(Math.abs(min)%60);return h?label3(`${h}小時${m?`${m}分鐘`:''}`,`${h}h ${m?`${m}m`:''}`,`${h}시간 ${m?`${m}분`:''}`):label3(`${m}分鐘`,`${m} min`,`${m}분`);}
