  // selected pet, whether monitored, Blank, or New Pet.
  try {
   if(typeof state!=='undefined'){
    state.tab='home';state.detail=null;state.modal='';
    if(typeof render==='function')render(true);
   }
  } catch(err){console.error('DeepPet gallery initialization failed',err);}
