 // full-day scans on every pet switch. Keep the legacy branch only as a
 // compatibility fallback if the new detector was not loaded at all.
 if(!real&&root.DeepPetContextAlerts1061){
  const candidates=root.DeepPetContextAlerts1061.forCurrentPet(date,scored);
  if(Array.isArray(candidates))return candidates.flatMap(e=>e.kind==='combined'?[e.primary,e.secondary]:[e])
   .filter(e=>e&&['heart','breath'].includes(e.kind))
   .map(e=>({...e,type:e.type||((e.value??0)>=(e.reference??0)?'high':'low'),deviation:e.relative||0}));
 }
 const scoredEvents=(scored.integrity?.alerts||[]).filter(e=>['heart','breath'].includes(e.kind)&&e.date===date&&Number.isFinite(e.value)&&Number.isFinite(e.minute))
  .map(e=>({...e,type:e.value>=e.reference?'high':'low',deviation:e.relative??0}))
  .sort((a,b)=>(b.relative||0)-(a.relative||0));
 if(real||scoredEvents.length)return scoredEvents;
 // Investor-gallery profiles: only their dated valid minute traces may
 // produce a timed episode. Never copy a showroom event into real/new pets.
