 const breedLabel=p?.breed?.[state.lang]||p?.breed?.[state.lang==='zht'?'zht':state.lang==='zh'?'zh':'en']||p?.breed?.en||p?.breed?.zh||'';
 const meta=A.profileBasicsComplete(p)?`<p class="dp941-profile-meta">${esc941(breedLabel)} · ${Number(p.age).toFixed(1)} ${t('歲','岁','years','세','歳')} · ${Number(p.weight).toFixed(1)} kg</p>`:'';
 const basis=t('依品種、年齡、體重與個體有效記錄整理；體檢項目僅參考適用且可核對的檢驗區間。','依品种、年龄、体重与个体有效记录整理；体检项目仅参考适用且可核对的检验区间。','Based on breed, age, weight and qualified readings; exams are considered only with applicable verified ranges.','품종·나이·체중과 유효 기록을 바탕으로 하며 검진 결과는 확인된 참고범위만 반영합니다.','品種・年齢・体重と有効記録に基づき、検査結果は確認できる適用範囲のみ参照します。');
 const caption=`<p class="dp941-prevention-note">${esc941(data.message)}</p>`;
 const priorityTitle=t('推估需要留意的重點','推估需要留意的重点','Pet-specific care priorities','개별 건강 권장','推定される注意点');
 const emptyNames=[
  t('依品種與年齡的日常照護','依品种与年龄的日常照护','Routine care for this breed and life stage','품종과 연령에 따른 일상 관리','品種と年齢に応じた日常ケア'),
  t('體重與身體狀態','体重与身体状态','Weight and body condition','체중과 체형','体重と体の状態'),
  t('適合年齡的每日活動','适合年龄的每日活动','Age-appropriate daily activity','연령에 맞는 일상 활동','年齢に合う日々の活動')
 ];
 // The shell stays structurally identical for Blank, Lucky and measured pets.
