 const unavailableRows=emptyNames.map((label,i)=>`<button type="button" class="dp941-care-row" disabled aria-disabled="true"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc941(label)}</strong><em>N/A</em></button>`).join('');
 const content=!data.available?`<h3>${priorityTitle}</h3><div class="dp941-care-list">${unavailableRows}</div><p class="dp941-empty-prevention">${esc941(data.message)}</p>`:`<h3>${priorityTitle}</h3><div class="dp941-care-list">${items.slice(0,3).map((x,i)=>`<button type="button" class="dp941-care-row" data-action="dp70-watch-open" data-code="${esc941(x.code)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc941(x.name)}</strong><em>${x.source==='monitoring'?'◉':'↗'}</em></button>`).join('')}</div>${items.length>3?`<button type="button" class="dp941-prevent-more" data-action="dp905-watch-more">${t('查看全部','查看全部','View all','전체 보기','すべてを見る')} · ${items.length} →</button>`:''}${caption}`;
