 function picture(model,klass){
  const type=model==='4g'?'4g':'bt';
  return `<img class="${klass}" data-dp-product="${type}" src="${photo(type)}" alt="${name(type)}" decoding="async"/>`;
 }
 const originalWizard=wizardView;
